/**
 * Git-independent guard for the same claim safety-strength-regression.test.ts
 * makes against Desktop's own history (OLD 03f98fdd~1, WEAK 03f98fdd):
 * Schlusspruefung Inhaltsschutz (Opus 5, 18.09.2026), Punkt 4 found that the
 * history-based file goes RED, not skipped, in CI, because `ci.yml` checks
 * out with the default `fetch-depth: 1` and the historical git objects are
 * unreachable there.
 *
 * FROZEN_FLOOR below is a one-time snapshot, generated by running the exact
 * probe generator from safety-strength-regression.test.ts (STRICT_PROBES
 * plus CSAM_CHUNK_PROBES) against BOTH the pre-regression fassung (OLD,
 * loaded once via `git show 03f98fdd~1:...` on a machine that had the
 * history) and the fassung shipped in this commit, and keeping the LOWER of
 * the two ranks per pattern (`Math.min(rank(oldCheck(p)), rank(currentCheck(p)))`).
 * That means: 438 of 444 unique patterns are frozen at OLD's full-strength
 * floor (3, "csam"; the probe generator produces some patterns more than
 * once from different angles, hence 444 unique out of 455 generated), and
 * the remaining 6 are a small, counted exception where CURRENT is
 * deliberately weaker than OLD (the "csa m"-style two-block split with a
 * block over 2 characters, the accepted
 * residual named in safety.ts at SHORT_TERM_GLUE_MAX_LENGTH) is frozen at
 * CURRENT's own, lower, already-accepted floor. Nothing here is a copy of
 * ALT/WEAK's word lists: the patterns are the SAME mechanically generated
 * probes this repo already ships in safety-strength-regression.test.ts, and
 * the numbers are just historical verdicts on them, not source code.
 *
 * This file runs in EVERY checkout, shallow or not, and can go red: a future
 * change that weakens any of these patterns below its frozen floor fails
 * here regardless of git history. It does not replace
 * safety-strength-regression.test.ts (which still carries the live,
 * regenerable comparison, the residual-ceiling tests, and the negative
 * controls); it is the part of that file's claim that must survive a
 * shallow CI checkout.
 *
 * To regenerate after a deliberate, reviewed change to the probe set or to
 * safety.ts's guaranteed floor: temporarily add a test to
 * safety-strength-regression.test.ts that dumps
 * `[...STRICT_PROBES, ...CSAM_CHUNK_PROBES].map((p) => [p, Math.min(rank(oldCheck(p)), rank(currentCheck(p)))])`
 * to a file, dedupe by pattern, and paste the result in below. Never hand-edit
 * individual rows.
 */
import { describe, it, expect } from 'vitest'
import { checkPromptSafety as currentCheck } from '../safety'

type Verdict = { blocked: boolean; reason?: string }

/** Same ladder as safety-strength-regression.test.ts: unblocked(0) < any
 *  other block reason (1) < minor+sexual(2) < csam(3). */
function rank(v: Verdict): number {
  if (!v.blocked) return 0
  if (v.reason === 'csam') return 3
  if (v.reason === 'minor+sexual') return 2
  return 1
}

