describe('frozen floor: every pattern stays at or above its historically measured minimum', () => {
  it('CURRENT never drops below the frozen minimum rank for any pattern', () => {
    const regressions: string[] = []
    for (const [pattern, minRank] of FROZEN_FLOOR) {
      const actual = rank(currentCheck(pattern))
      if (actual < minRank) {
        regressions.push(`"${pattern}": expected >= ${minRank}, got ${actual} (${JSON.stringify(currentCheck(pattern))})`)
      }
    }
    expect(regressions, regressions.join('\n')).toEqual([])
  })

  it('sanity: the table is not degenerate', () => {
    expect(FROZEN_FLOOR.length).toBeGreaterThan(400)
    const atFullStrength = FROZEN_FLOOR.filter(([, r]) => r === 3).length
    const accepted = FROZEN_FLOOR.filter(([, r]) => r < 3).length
    expect(atFullStrength).toBeGreaterThan(400)
    // The accepted, named exception (residual chunked/glued "csam" over the
    // glue boundary) is small and counted; if this grows without a matching
    // update to safety.ts's own comments, something regenerated the table
    // over a real weakening instead of a reviewed one.
    expect(accepted).toBeLessThanOrEqual(10)
  })
})
